#!/usr/bin/env bash
# Stage B -- regenerate everything under generated/ (all git-ignored):
#   generated/ppu/   lifted PPU code + ppu_recomp.h
#   generated/spu/   lifted SPU images + the fingerprint workload registry
# The NID -> HLE handler table is generated by CMake at configure time.
#
# Re-run after: bumping ps3recomp.pin, switching EBOOT (e.g. installing the
# title update), or editing analysis/functions.overrides.json.
#
#   tools/relift.sh [--ppu-only]
# --ppu-only regenerates generated/ppu only (function boundaries, PPU lift,
# post-lift hooks) and leaves generated/spu alone: for a PPU-lifter-only or
# continuation-list change (save-state continuations, config/ss_cont_list*.txt),
# where the SPU lift would come out identical but its rewrite would rebuild
# every SPU image.
set -euo pipefail
PPU_ONLY=0
[ "${1:-}" = "--ppu-only" ] && PPU_ONLY=1
# SPU lifts group basic blocks into call-graph regions (in-region branches are
# gotos instead of dispatcher hops); SPU_LIFT_REGIONS=0 restores the old lift.
export SPU_LIFT_REGIONS="${SPU_LIFT_REGIONS:-1}"
# spu_lifter.py --reg-cache (SPU_LIFT_RCACHE) is verified for tools/lift_jobs.sh's
# spu_jobs and tools/lift_jobchain.py's spu_jobchain only: never for these lifts.
export SPU_LIFT_RCACHE=0
cd "$(dirname "$0")/.."
# Windows installs "python" (and a Microsoft Store stub named python3); prefer a python3 that really runs.
if [ -z "${PYTHON:-}" ]; then
    if python3 -c "" >/dev/null 2>&1; then PYTHON=python3; else PYTHON=python; fi
fi
PY="$PYTHON"
SDK="${PS3RECOMP:-external/ps3recomp}"
JOBS="${JOBS:-$(nproc 2>/dev/null || echo 4)}"

[ -f analysis/EBOOT.functions.json ] || { echo "run tools/analyze.sh first"; exit 1; }
EBOOT="$("$PY" -c 'import json;print(json.load(open("analysis/inputs.json"))["eboot"])')"
CODE_END="$(tail -n1 analysis/code_end.txt)"

# ---- function boundaries --------------------------------------------------
# Seed from the .opd table (ppu_loader) and, if analyze.sh ran it, Ghidra's
# call-graph-recovered starts; then let the heuristic scanner fill the rest.
SEEDS=(--seed-json analysis/EBOOT.functions.json)
[ -f analysis/ghidra/functions.json ] && SEEDS+=(--seed-json analysis/ghidra/functions.json)
[ -f analysis/functions.overrides.json ] && SEEDS+=(--seed-json analysis/functions.overrides.json)
"$PY" "$SDK/tools/find_functions.py" "$EBOOT" "${SEEDS[@]}" --output analysis/functions.json

# ---- the title's addresses in this EBOOT ----------------------------------
# tools/if2_resolve.py finds every address the title code uses (hooks, globals, patched instructions) in this
# EBOOT by code patterns (config/if2_sigs.json) and writes generated/if2_resolved.h (src/ compiles with it),
# analysis/resolve.json (ppu_postlift.py, extract_policy_modules.py) and analysis/resolve_report.txt (printed
# here, so the launcher's log holds it). On a US EBOOT every value is cross-checked; a mismatch stops the lift.
mkdir -p generated
"$PY" tools/if2_resolve.py resolve
KNOWN="$("$PY" -c 'import json;print(json.load(open("analysis/resolve.json")).get("known") or "")')"

# ---- PPU lift -------------------------------------------------------------
# --hle-stubs: each import trampoline becomes ps3_hle_call(nid). Without it the
#              first firmware call jumps to 0x39800000 (`li r12,0`) and dies.
# --code-end : stops .rodata in the R-X segment being lifted as code.
rm -rf generated/ppu && mkdir -p generated/ppu
NAMES=()
if [ -f analysis/ghidra/symbols.json ] && [ -f "$SDK/tools/ghidra_names.py" ]; then
    "$PY" "$SDK/tools/ghidra_names.py" analysis/ghidra -o analysis/names.json \
        && NAMES=(--names analysis/names.json) || true
fi
# --cont-list: save-state continuations (ppu_recomp_cont.cpp; docs/NOTES.md
#              2026-10-15). Grow the list from the SS_SELFRESUME / PPU_RESUME_CHECK_EVERY
#              "missing" reports (tools/ss_selfresume.py --missing).
#              One list per EBOOT build: ss_cont_list.txt is the disc EBOOT's, ss_cont_list.104.txt
#              title update 1.04's (eboot_map.py translate of the disc list; what did not map is listed
#              at its end). Any other EBOOT: both lists carried over function by function by
#              if2_resolve.py (analysis/ss_cont_list.resolved.txt).
CONT=()
case "$KNOWN" in
    us100) CONT_LIST=config/ss_cont_list.txt ;;
    us104) CONT_LIST=config/ss_cont_list.104.txt ;;
    *)     CONT_LIST=analysis/ss_cont_list.resolved.txt ;;
esac
[ -f "$CONT_LIST" ] && CONT=(--cont-list "$CONT_LIST")
"$PY" "$SDK/tools/ppu_lifter.py" "$EBOOT" \
    --functions analysis/functions.json \
    --hle-stubs analysis/EBOOT.imports.json \
    --code-end "$CODE_END" \
    --jobs "$JOBS" \
    "${NAMES[@]}" \
    "${CONT[@]}" \
    -o generated/ppu

# ---- post-lift call hooks -------------------------------------------------
# Title code that has to run inside a lifted function (src/infamous2_hooks.cpp,
# e.g. if2_fmv_quad: wide-screen movie fit). Idempotent; a hook whose anchor
# moved is reported and left out, it never fails the lift.
"$PY" tools/ppu_postlift.py generated/ppu

# ---- SPU lift -------------------------------------------------------------
if [ "$PPU_ONLY" = 1 ]; then
    echo "(--ppu-only: generated/spu left as it is)"
elif compgen -G "analysis/spu_images/*.elf" > /dev/null; then
    rm -rf generated/spu && mkdir -p generated/spu   # CMake compiles every generated/spu/*/
    # Bink (image 2) resumes after its receive_event / tryreceive_event stops
    # (0xFA14 / 0xFA8C); lift those continuations instead of interpreting them.
    # The image is named after its EBOOT offset (spu_0001_at_0085E380 on the disc,
    # spu_0001_at_008BCE00 in update 1.04): take whichever this EBOOT has.
    BINK=(); for f in analysis/spu_images/spu_0001_at_*.elf; do
        [ -f "$f" ] && BINK=(--extra-funcs "$(basename "${f%.elf}")=0xFA18,0xFA90"); done
    "$PY" "$SDK/tools/build_spu_workloads.py" \
        --images analysis/spu_images \
        --lifted generated/spu --relift \
        "${BINK[@]}" \
        --out generated/spu/spu_workloads.c \
        --register-fn infamous2_spu_register_all --constructor --title infamous2
else
    echo "(no static SPU images -- skipping SPU lift)"
fi

echo
echo "Lift done. Build:  cmake -B build -G Ninja && cmake --build build"
